BEGIN;

-- gcp-pcde
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pcde-q1": {"point": "『今あるものだけでなく将来作られるものにも自動で効くか』が判断軸なら、階層の一番上（組織）にポリシーを置いて継承させる。", "eg": "マンションの管理規約は、管理組合（組織）で一度決めておけば、あとから入居してくる部屋にも自動的に適用される。部屋ごとに契約書を書き直す必要はない。"}, "gcp-pcde-q2": {"point": "『複数人が同時に触ると壊れる共有ファイルをどう守るか』と問われたら、GCSリモートbackend＋stateロックが定石。", "eg": "銀行の共同口座の通帳を複数人が同時に記帳すると数字がずれる。だから窓口で『処理中』の札を立てて、一人ずつ順番に処理する。"}, "gcp-pcde-q3": {"point": "『ガードレール込みで基盤を短期間に立ち上げたい』なら、ゼロから作らずGoogle推奨のブループリント（CFT）を土台にする。", "eg": "新入社員研修で、一から自己流のマニュアルを作らせるのではなく、実績のある研修プログラムのテンプレートを配って始めさせる。"}, "gcp-pcde-q4": {"point": "『長期の鍵を保管せずに外部から認証したい』ならWorkload Identity Federation（外部IDトークンで短命の認証情報を都度発行）。", "eg": "ホテルのフロントで、宿泊者ごとに合鍵を作って渡すのではなく、来るたびに身分証を見せてその場限りのカードキーを発行してもらう方式。"}, "gcp-pcde-q5": {"point": "『ブランチごとに本番から隔離した使い捨て環境を自動で作って消したい』なら、Terraform＋GKE名前空間で動的生成し、マージ後に破棄する。", "eg": "展示会で商品ブースをブランチごとに毎回組み立てて、会期が終わったら解体して片付ける。常設店舗（共有ステージング）は作らない。"}, "gcp-pcde-q6": {"point": "『パイプライン用サービスアカウントにどんな権限を与えるか』と問われたら、タスクに必要な最小限の事前定義ロールだけを付与し、不要になれば見直す。", "eg": "アルバイトに渡すのはレジの鍵だけ。店の金庫やオフィス全部の鍵を、楽だからといって渡したりしない。"}, "gcp-pcde-q7": {"point": "『Terraformの実行とstate管理そのものをGoogleにマネージドで任せたい』ならInfrastructure Manager。", "eg": "自分の車を毎回自分で運転するのではなく、運行の管理ごとタクシー会社に委託するようなもの。"}, "gcp-pcde-q8": {"point": "『pushをきっかけに自動でビルド/テストを走らせたい』ならCloud Buildのpushトリガー＋cloudbuild.yaml。人が起点の工程は必ず抜ける。", "eg": "郵便受けに手紙が届いた瞬間、自動で開封して仕分けする機械を置くようなもの。人が見に行く手間も見逃しもない。"}, "gcp-pcde-q9": {"point": "『コンテナ/パッケージの保存・版管理・脆弱性スキャンをどこでやるか』と問われたら、現行推奨はArtifact Registry（GCRは旧世代で新規採用しない）。", "eg": "引っ越しのたびに使っていた古い運送会社ではなく、今の主力会社に荷物を預ける。旧会社は今も動くが、新しい依頼はもう出さない。"}, "gcp-pcde-q10": {"point": "『dev→staging→prodと承認を挟みながら段階的に届けたい』ならCloud Deployのデリバリーパイプライン。", "eg": "新商品を『試作品→社内モニター→店頭』と段階を踏んで、各段階でOKサインをもらってから次に進めるようなもの。"}, "gcp-pcde-q11": {"point": "『本番トラフィックを流さずに新版を検証してから徐々に移したい』なら、トラフィック0のタグ付きリビジョンで検証し、そこから割合を段階的に移す。", "eg": "新しい看板メニューを、まず常連客だけが知る裏メニューとして出し、評判が良ければ徐々に正式メニュー表に載せていく。"}, "gcp-pcde-q12": {"point": "『署名（アテステーション）された正規のイメージだけを通したい』ならBinary Authorizationのデプロイポリシー。", "eg": "空港の搭乗ゲートで、正規のチケット（署名）を持つ乗客だけを通す関所。手荷物検査（脆弱性スキャン）とは別の確認。"}, "gcp-pcde-q13": {"point": "『少人数からリスクを試して、問題なければ広げたい』ならカナリアデプロイ。", "eg": "新商品の試食コーナーを、まず一部の売り場だけに置いて反応を見てから、全店舗に展開するようなもの。"}, "gcp-pcde-q14": {"point": "『イメージに含まれる既知の脆弱性そのものを自動検査したい』ならArtifact Analysis。署名の有無を見るBinary Authorizationとは別物。", "eg": "食品工場で金属探知機に通し、異物（脆弱性）が混入していないか機械的にチェックする検査ライン。"}, "gcp-pcde-q15": {"point": "『欠陥をデプロイ前に見つけたい』ならCloud Buildのステップにテストを組み込み、失敗したらそこでデプロイを止める。", "eg": "料理を客に出す前に味見をして、まずければ出す前に作り直す。出してから『まずかった』と気づくのでは遅い。"}, "gcp-pcde-q16": {"point": "『成果物がどのソース・どのビルドで作られたかを検証したい』ならCloud Buildが生成するビルド来歴（provenance）。ラベルやログは検証にならない。", "eg": "ワインのラベルにある第三者機関の原産地証明書。産地を自己申告で書くだけのラベルと違い、外部から確認できる形で来歴を証明する。"}, "gcp-pcde-q17": {"point": "『実際に測った数値そのもの』を聞かれたらSLI。目標（SLO）でも契約（SLA）でもない。", "eg": "マラソンの『実際に出したタイム』がSLI。『目標タイム』はSLO、『大会規約に書かれた罰則規定』はSLA。"}, "gcp-pcde-q18": {"point": "『社内の目標か、客との契約（違反にペナルティ）か』で見分ける。目標がSLO、契約がSLA。", "eg": "ダイエットで自分で決めた『目標体重』がSLO。トレーナーとの『達成できなければ返金する契約』がSLA。"}, "gcp-pcde-q19": {"point": "『許容できる不調の量』を求められたら1−SLO。99.9%なら0.1%。", "eg": "100点満点のテストで合格ラインを98点と決めたら、残り2点分までは間違えても合格圏内、という『許容できる失点』の枠。"}, "gcp-pcde-q20": {"point": "『バジェットを使い切った後どうするか』を問われたら、機能凍結と信頼性改善へのエンジニアリング投入の2つ。SLOを下げる・集計をリセットするなど数値をいじる対応は誤り。", "eg": "会社の交際費予算を使い切ったら、新しい接待を止めて経費の使い方を見直す。予算科目を後から水増しして帳尻を合わせても、実態は何も良くならない。"}, "gcp-pcde-q21": {"point": "『手作業・繰り返し・自動化可能・価値が蓄積しない』作業がトイル。対処は自動化して減らす。", "eg": "毎日同じ枚数の紙の書類を手で仕分ける作業。件数が増えるほど人手も比例して増え、いくらこなしても新しい価値は生まれない。だから仕分け機（自動化）に投資する。"}, "gcp-pcde-q22": {"point": "『ユーザー視点でサービスの健康状態を見る4指標』と言われたら、レイテンシ・トラフィック・エラー・サチュレーション。", "eg": "人間ドックの基本4項目（血圧・脈拍・体温・呼吸数）のようなもの。専門検査を全部やらなくても、この4つでまず全体の健康状態がつかめる。"}, "gcp-pcde-q23": {"point": "『大規模障害で誰が全体を指揮し意思決定するか』と問われたらインシデントコマンダー。", "eg": "手術室で、実際に手を動かす執刀医とは別に、全体の進行と判断を仕切るオペレーションディレクターを置くようなもの。"}, "gcp-pcde-q24": {"point": "『事後分析で何に焦点を当てるか』と問われたら、個人の非難ではなく仕組み・プロセスの改善。", "eg": "飛行機事故の調査委員会は、操縦したパイロット個人を罰することより、なぜその操作が可能な設計だったのかを調べて再発防止に活かす。"}, "gcp-pcde-q25": {"point": "『ユーザー視点の可用性を測る式』と問われたら、成功リクエスト数÷全リクエスト数。", "eg": "通販で『無事に届いた注文数÷発注した注文数』の割合。倉庫の稼働率（内部指標）ではなく、客に届いたかどうかを見る。"}, "gcp-pcde-q26": {"point": "『VMからログとメトリクスを収集する現行の推奨エージェント』と問われたらOps Agent。旧2エージェントの新規導入は避ける。", "eg": "昔は郵便配達員と新聞配達員が別々に来ていたが、今は1人の配達員がまとめて届けてくれるようなもの。"}, "gcp-pcde-q27": {"point": "『特定のログの件数を時系列指標にしてアラートまで出したい』ならログベースメトリクス。", "eg": "受付で『特定の来客用件』が来るたびに手元のカウンターを1つ押し、その集計をそのままグラフとアラームにつなげる仕組み。"}, "gcp-pcde-q28": {"point": "『ログを長期保管して大規模SQL分析したい』ならログルーターのシンクでBigQuery/GCSへエクスポート。保持期間の延長では器が違う。", "eg": "会社の紙の伝票を、廃棄期限が来る前にすべてスキャンして外部の書庫会社に預け、あとで検索・分析できるようにする。"}, "gcp-pcde-q29": {"point": "『取り込み時点でログのコストを抑えたい』ならログルーターの除外フィルタ。保持期間の短縮や事後の集計では、既に発生した取り込み課金は減らせない。", "eg": "電話の勧誘を、着信してから切るのではなく、着信拒否リストに登録して最初から鳴らないようにする。"}, "gcp-pcde-q30": {"point": "『GKEのPrometheus形式メトリクスを大規模かつマネージドで扱いたい』ならManaged Service for Prometheus（GMP）。", "eg": "自社で発電設備を持って運用するより、電力会社（マネージドサービス）から電気を買う方が、規模が大きくなっても安定して楽。"}, "gcp-pcde-q31": {"point": "『マイクロサービス間のどこで時間を消費しているか』を特定したいならCloud Trace（分散トレース）。", "eg": "駅伝で、どの区間の選手が一番タイムを落としたかを区間ごとのストップウォッチで計るようなもの。"}, "gcp-pcde-q32": {"point": "『本番のどの関数がCPU/メモリを食っているか低オーバーヘッドで継続的に知りたい』ならCloud Profiler。", "eg": "家庭の電気代が高いとき、コンセントごとに電力計をつけっぱなしにして、どの家電が一番電気を食っているか継続的に測る。"}, "gcp-pcde-q33": {"point": "『監査ログの既定挙動』を問われたら、管理アクティビティは常時ON・無効化不可、データアクセスは既定OFFで明示的な有効化が要る、の2点セット。", "eg": "図書館の入館記録（いつ誰が来たか）は自動で毎回記録される。一方、書棚のどの本を手に取ったかまでは、特別に閲覧記録の設定を有効にしない限り残らない。"}, "gcp-pcde-q34": {"point": "『条件を満たしたら通知する仕組みに必要な2要素』は、条件を定めるアラートポリシーと、宛先を定める通知チャネル。", "eg": "目覚まし時計は『何時に鳴らすか（条件）』と『どのスピーカーで鳴らすか（通知先）』の両方を設定して初めて機能する。"}, "gcp-pcde-q35": {"point": "『外部から能動的に定期確認したい』ならuptime check／合成モニタ。内部のヘルスチェックや実トラフィック頼みの指標監視とは別物。", "eg": "お店の定休日にも、外から定期的に『今日は本当に開いているか』と電話をかけて確認するようなもの。"}, "gcp-pcde-q36": {"point": "『過剰プロビジョニングのVMサイズを見直したい』ならRecommender/Active Assistのrightsizing推奨をまず確認して適用する。勘や一律縮小ではない。", "eg": "ダイエットで、体重計の実測データに基づいたアドバイスを受ける。見た目の印象だけで運動メニューを決めない。"}, "gcp-pcde-q37": {"point": "『1年以上安定して常時稼働するワークロードのコストを下げたい』なら確約利用割引（CUD）。継続利用割引は自動だが割引が浅く、Spotは中断前提。", "eg": "毎日同じジムに通うなら、都度払いより年間契約（前払い割引）の方が安い。たまにしか行かないなら年間契約は損。"}, "gcp-pcde-q38": {"point": "『GKEでPod数とノード数の両方を自動でスケールしたい』なら、PodはHorizontal Pod Autoscaler、ノードはCluster Autoscalerと役割が分かれている。", "eg": "フードコートで、混雑時にレジの台数（Pod）を増やすのと、建物自体を増築して席数（ノード）を増やすのは、別の判断・別の担当。"}, "gcp-pcde-q39": {"point": "『コールドスタートを抑えつつオートスケールも活かしたい』なら最小インスタンス数を設定する。0固定でも最大固定でもない。", "eg": "来客の少し前からストーブを点けて部屋を暖めておく（最小インスタンス）。来客が増えたらエアコンも追加で稼働させる（オートスケール）。"}, "gcp-pcde-q40": {"point": "『直近の変更が疑われる障害で最初に何をするか』と問われたら、まず緩和（ロールバック等）で復旧し、根本原因の調査は復旧後に行う。", "eg": "家で水漏れが起きたら、原因の配管を特定する前に、まず元栓を閉めて被害を止める。原因調査はそのあとでいい。"}, "gcp-pcde-q41": {"point": "『IDE内のコード補完、コンソールでの運用相談、ターミナルでの自動化』のどこで作業しているかで、順にCode Assist・Cloud Assist・CLIと担当が分かれる。", "eg": "会社の中で、デスクの相談窓口（IDE＝Code Assist）、受付フロアの相談窓口（コンソール＝Cloud Assist）、電話窓口（ターミナル＝CLI）がそれぞれ別の担当者になっているようなもの。"}, "gcp-pcde-q42": {"point": "『アプリ用CI/CDをMLモデルのデプロイに流用するとき何を追加するか』と問われたら、単体テストに加えてモデル精度やデータドリフトなどモデル品質の指標を評価ステージに組み込みゲートする。", "eg": "車の完成検査で、部品（コード）が仕様通りに組み立てられているかの検査に加えて、実際に走らせた燃費や乗り心地（モデルの精度）も別枠でチェックする。部品検査だけでは走行性能の劣化は見抜けない。"}, "gcp-pcde-q43": {"point": "『AIのログ分析支援をどう使うか』と問われたら、自然言語で仮説を出させ、裏付けと最終判断は人が行う、という役割分担が正しい。", "eg": "医者が問診（AI）から病気の見当をつけても、確定診断には検査結果という裏付け（人の確認）を必ず照合してから診断書を書く。"}, "gcp-pcde-q44": {"point": "『メトリクス悪化の原因の見当がつかない場面でのAI活用』は、AIに手がかりを出させて調査の起点にする使い方が正しい。SLO基準を緩めたり、AIの答えをそのまま確定原因にするのは誤り。", "eg": "探偵ドラマで、助手（AI）が現場の手がかりを素早く洗い出しても、犯人の断定（原因の確定）は刑事（人）が裏を取ってから行う。"}, "gcp-pcde-q45": {"point": "『スパンが多すぎて追えないときのトレース分析支援の使い方』は、AIに遅延の主要スパンを絞り込ませ、そこから先を人が詳しく調べる、という分業が正しい。", "eg": "大量の防犯カメラ映像から、AIが『怪しい場面』を絞り込んでくれても、実際にその場面を見て判断するのは警備員（人）の仕事。"}, "gcp-pcde-q46": {"point": "『手動で全リソースを洗い出す前に何を確認するか』と問われたら、Active Assistが継続的に出す推奨事項（アイドルリソースの削除等）をまず確認する。実行するかは人の判断。", "eg": "家中のコンセントを全部見て回らなくても、スマート電力計（Active Assist）が『このコンセントは使われていません』と教えてくれる。抜くかどうかは自分で判断する。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pcde')
  AND q.explanation_data IS NOT NULL;

-- gcp-pcde-c
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pcde-c-q1": {"point": "ネットワークとファイアウォールは一元管理したいが、各チームにはVMやGKEを自由に作らせたいなら共有VPCのホスト/サービスプロジェクト構成。", "eg": "商店街に例えると、道路や街灯(ネットワークとファイアウォール)は商店街組合(ホストプロジェクト)が一括管理し、各店舗(サービスプロジェクト)は店内の商品棚を自由に配置できる、という役割分担に近い。"}, "gcp-pcde-c-q2": {"point": "本番をブロックせずに影響だけ先に知りたいなら、組織ポリシーのドライランモードで試す。", "eg": "電車の新しいダイヤ改正を、実際に運行を止めずに『もし今このダイヤだったら何本の電車が遅れていたか』だけをシミュレーションしてみる、というイメージ。"}, "gcp-pcde-c-q3": {"point": "Cloud BuildをVPC Service Controlsで守りたいなら、まずプライベートプールに切り替える。デフォルトプールのままではどう設定しても境界に入れられない。", "eg": "宅配便を自宅の宅配ボックス(境界内)で受け取りたいのに、配達員が共同玄関(デフォルトプール)までしか来られない契約になっている。専用の宅配ボックス(プライベートプール)を設置して初めて境界の中で受け取れる。"}, "gcp-pcde-c-q4": {"point": "シークレットの値を読むだけならsecretAccessorをそのシークレット単位で付与する。プロジェクト全体に及ぶadmin/ownerは渡さない。", "eg": "ホテルの部屋の鍵を渡すとき、その部屋のカードキー(シークレット単位のアクセス権)だけ渡せば十分で、ホテル全館のマスターキー(admin/owner)まで渡す必要はない。"}, "gcp-pcde-c-q5": {"point": "Kubernetes側の管理は手放すが実体のGoogle Cloudリソースは消したくないなら、deletion-policyをabandonにしてから削除・再適用する。", "eg": "引っ越しのとき、今の住所の登録(名前空間での管理)だけを抹消して家自体(実体のリソース)は解体せずそのまま残し、新しい住所で改めて登録し直す、というイメージ。"}, "gcp-pcde-c-q6": {"point": "フォルダ階層は最大10階層という固定の上限で、割り当て申請や設定変更では増やせない。それ以上必要なら階層設計自体を見直す。", "eg": "エレベーターが10階建てのビルにしか停まらない設計になっていて、業者に頼んでも11階を後付けできない。最初から10階以内に収まる建て方を考えるしかない。"}, "gcp-pcde-c-q7": {"point": "IAMの条件判定に使うならタグ、請求レポートでの分類に使うならラベル。", "eg": "社員証(タグ)はドアの鍵(IAM)を開けるために使い、経費精算の勘定科目コード(ラベル)は月末の集計にしか使わない、というように使う場面がそもそも違う道具。"}, "gcp-pcde-c-q8": {"point": "ブランチごとに権限を変えたいなら、ブランチパターン別にトリガー自体を分けて、トリガーごとに専用のサービスアカウントを割り当てる。", "eg": "レストランの厨房で、通常メニュー用のコンロと特別会席用のコンロを分け、それぞれ専属のシェフ(サービスアカウント)を割り当てる、というイメージ。"}, "gcp-pcde-c-q9": {"point": "featureブランチではplanで差分を見せるだけにし、mainへのマージという合意の瞬間にだけapplyで実際に反映する。", "eg": "レストランの調理は、注文が確定する(mainへのマージ)前は試作(plan)にとどめ、正式注文が入ってから初めて本番の調理(apply)を始める、というイメージ。"}, "gcp-pcde-c-q10": {"point": "canaryの今のフェーズから次のフェーズへ進めたいなら rollouts advance。ターゲット間の昇格であるpromoteとは操作対象が別。", "eg": "舞台の演出で、各幕が無事に終わったことを演出家が確認してから、手動で次の幕を上げる合図を出す、というイメージ。"}, "gcp-pcde-c-q11": {"point": "本番へのリリースに人の承認を必須にしたいなら、ターゲットのrequireApprovalをtrueにし、承認できる人にclouddeploy.approverロールを与える。", "eg": "ロケット発射前の最終ゴーサインを、資格を持つ管制官だけが出せるようにしておく、という仕組みに近い。"}, "gcp-pcde-c-q12": {"point": "本番を止めずに違反状況だけ先に知りたいなら、enforcementModeをDRYRUN_AUDIT_LOG_ONLYにしてAudit Logsで確認する。", "eg": "新しい火災報知器の感度設定を、実際にスプリンクラーを作動させずに『このままなら何回反応していたか』だけを裏で記録するテストモードにしておく、というイメージ。"}, "gcp-pcde-c-q13": {"point": "アテステーション待ちを飛ばして今すぐ通したいなら、対象のPodにbreakglassラベルをtrueで付ける。クラスタ全体の無効化はしない。", "eg": "病院で通常は処方箋がないと薬を出せないが、緊急時だけ医師の口頭指示で薬を出し、後から必ずカルテに記録を残す、という緊急運用に近い。"}, "gcp-pcde-c-q14": {"point": "一度付けたタグが別の中身を指さないようにしたいなら、Artifact Registryのイミュータブルタグを有効にする。", "eg": "本の初版・第2版という版数(タグ)を一度印刷したら、あとから中身だけこっそり差し替えられないように製本してしまう、という出版のルールに近い。"}, "gcp-pcde-c-q15": {"point": "消す前に何が消えるか確認したいなら、クリーンアップポリシーのドライランでログに出す。テスト用の複製や自作ツールは不要。", "eg": "引っ越し業者に見積もりだけ出してもらい、実際にトラックへ積み込む前に『何を運び出す予定か』のリストを先にチェックする、というイメージ。"}, "gcp-pcde-c-q16": {"point": "本番ビルドで意図しない切り替わりを防ぎたいなら、シークレットをバージョン番号で固定参照し、latestエイリアスに任せない。", "eg": "レシピ本の『最新版を毎回参照』ではなく『第3刷のこのページ』と決めておけば、出版社が新版を出しても勝手にレシピが変わらない、というイメージ。"}, "gcp-pcde-c-q17": {"point": "複数リージョンへ同時にデプロイし、どこか1つでも失敗したら全体を失敗として扱いたいならマルチターゲット。", "eg": "オーケストラの複数パート(弦・管・打楽器)が同じ指揮のもとで同時に演奏を始め、どれか1パートでも止まったら演奏全体を『失敗』として扱う、というイメージ。"}, "gcp-pcde-c-q18": {"point": "単一窓口で社内・公開の両方を透過的に取得しつつ社内を優先させたいなら、virtualリポジトリでstandardの優先度を高い数値に設定する。", "eg": "フリマアプリで、同じ商品名の出品があったとき、公式ストア(社内リポジトリ)の出品を検索結果の一番上に固定表示し、個人出品(公開リポジトリ)より優先させる設定に近い。"}, "gcp-pcde-c-q19": {"point": "本番デプロイを含むビルドだけ人の承認を必須にしたいなら、そのトリガーにrequire-approvalを付けて承認者ロールを渡す。デプロイ側の承認(Cloud Deploy)とは別物と区別する。", "eg": "工場のラインで、通常品は自動でベルトコンベアが流れるが、特別注文品だけは検査員のスタンプが押されるまでベルトが止まったままになる、という仕組みに近い。"}, "gcp-pcde-c-q20": {"point": "特定のファイル変更だけではビルドを起動させたくないなら、ignored filesフィルタに除外パターンを追加する。含めるファイル(included files)に入れると逆に反応が限定されてしまう。", "eg": "防犯カメラの動体検知で、駐車場の風で揺れる木だけは誤検知しないよう検知除外エリアに設定しておく、というイメージ。"}, "gcp-pcde-c-q21": {"point": "Spinnakerの構成もGitでバージョン管理したいなら、Spinnaker OperatorでSpinnakerServiceマニフェストとして宣言的に管理する。", "eg": "口頭指示や現場合わせで進める工事ではなく、必ず設計図面を書き起こしてから施工し、図面自体を保管して後から誰でも見返せるようにする、という現場管理のやり方。"}, "gcp-pcde-c-q22": {"point": "急な障害も緩やかな劣化も両方検知したいなら、短期間×高倍率のfast-burnと長期間×低倍率のslow-burnを2本立てで用意する。", "eg": "家計簿で、1日で急にお金を使い果たす『大きな出費』を見張るアラームと、毎日少しずつ使いすぎて月末に足りなくなる『じわじわ出費』を見張るアラームを、別々に設定しておくイメージ。"}, "gcp-pcde-c-q23": {"point": "エラーバジェットを使い切ったら、新機能のリリースは止めて信頼性回復に人と時間を振り向ける。SLO目標値をいじって数字上だけ帳尻を合わせない。", "eg": "ダイエット中に体重の許容ライン(エラーバジェット)を超えたら、新しいご馳走(新機能)は我慢して運動(信頼性回復の施策)に専念する。体重計の目盛りを甘く書き換える(SLO目標値の引き上げ)のは解決になっていない、というイメージ。"}, "gcp-pcde-c-q24": {"point": "軽い超過は制限だけ、しつこい超過だけ一時BANしたいなら、レート制限のしきい値とBANのしきい値を別々に持つレートベースBANルールを使う。", "eg": "図書館で、返却期限を1回過ぎただけなら延滞金だけで済ませ、何度も繰り返す常習者だけ一定期間貸出停止にする、という2段階のペナルティ制度に近い。"}, "gcp-pcde-c-q25": {"point": "L7 DDoSのパターンを自動検知し、人手を介さず緩和ルールまで自動配備したいなら、Adaptive Protectionを有効化する。", "eg": "免疫システムが、体内に入ってきた未知の病原体のパターンを学習し、次に似た病原体が来たら自動的に抗体(緩和ルール)を作って対応する、というイメージ。"}, "gcp-pcde-c-q26": {"point": "連続してエラーを出すバックエンドだけを自動でプールから外し健全な方へ振り向けたいなら、consecutiveErrorsとbaseEjectionTimeで外れ値検出を設定する。", "eg": "合唱団で、明らかに音を外し続けているメンバーだけを一時的にステージから下げて休ませ、残りのメンバーで歌い続ける、というイメージ。"}, "gcp-pcde-c-q27": {"point": "独立した2つのリージョンLB間で自動フェイルオーバーしたいなら、Cloud DNSのフェイルオーバールーティングポリシーにヘルスチェックと短いTTLを組み合わせる。", "eg": "電話の転送設定で、いつもの窓口(主リージョン)が話し中(異常)のときだけ自動的に別の窓口(バックアップリージョン)へ転送されるようにしておく、というイメージ。"}, "gcp-pcde-c-q28": {"point": "即座にロールバックしたいなら、前のサーバーグループがまだ待機しているred/blackで切り替えるだけにする。作り直し(再デプロイ)は選ばない。", "eg": "電気のブレーカーが落ちたとき、新しい配線をやり直すのではなく、待機していた予備の電源にスイッチひとつで切り替える、というイメージ。"}, "gcp-pcde-c-q29": {"point": "本番トラフィックに一切触れさせず検証してから切り替えたいなら、--no-trafficと--tagでタグ付きURLを発行する。", "eg": "新商品を店頭には並べず、社内モニター(タグ付きURL)にだけこっそり試してもらい、問題なければ店頭の看板を一気に切り替える、というイメージ。"}, "gcp-pcde-c-q30": {"point": "at-least-once配信でのリトライによる重複を防ぎたいなら、イベントIDをドキュメントIDに使って冪等に書き込む。重複配信自体は止められない前提で考える。", "eg": "同じ宛名ラベル(イベントID)の荷物が2回届いても、同じ棚(同じドキュメントID)に置き直すだけで、棚の中身が二重にならない、という仕組み。"}, "gcp-pcde-c-q31": {"point": "プライマリが特定の台数を下回ったらフェイルオーバーさせたいなら、比率は『発動させたい下限台数÷プライマリ台数』で計算する(この設問では2÷5=0.4)。", "eg": "発電所で、5台ある発電機のうち稼働台数が2台を割り込んだら予備発電機に切り替える、という設備の待機ルールを比率で表現したものに近い。"}, "gcp-pcde-c-q32": {"point": "検証テストのコードだけが悪かったなら、アプリは再デプロイせず失敗したジョブだけをrollouts retry-jobでやり直す。", "eg": "試験の採点ミスが発覚したとき、受験者に再試験を課すのではなく、採点だけをやり直す、というイメージ。"}, "gcp-pcde-c-q33": {"point": "標準的な情報はSemantic Conventionsの決まった属性名で表し、独自情報はSetAttributesで追加する。スパン名やラベルに情報を詰め込まない。", "eg": "引っ越しの荷物リストで、住所や氏名などの共通項目は指定の様式(Semantic Conventions)通りに書き、それ以外の『割れ物注意』のようなメモは自由記入欄(カスタム属性)に書く、というイメージ。"}, "gcp-pcde-c-q34": {"point": "ログが遅れて届くことで誤検知するなら、しきい値をいじるのではなくアラインメント期間(集計の窓)を広げて遅延到着を吸収する。", "eg": "電車の改札の締め時刻を厳しくしすぎると、少し遅れて改札を通った定期客まで『無断入場』扱いになってしまう。締め時刻に余裕を持たせれば正しくカウントされる、というイメージ。"}, "gcp-pcde-c-q35": {"point": "サービス間でトレースをつなげたいなら、各サービスがtraceparentヘッダーを受信・抽出して次のリクエストへ伝播するようコードで実装する。ネットワークや権限の設定だけでは繋がらない。", "eg": "伝言ゲームで、前の人から聞いた合言葉(トレースID)を次の人にちゃんと伝えないと、途中で別の話として扱われてしまう、というイメージ。"}, "gcp-pcde-c-q36": {"point": "1回のリクエストの中でどのサービスが遅いか特定したいなら、Cloud Traceのウォーターフォール表示で各スパンの所要時間を比較する。", "eg": "料理の配膳で、注文から着席までの各工程(仕込み・調理・盛り付け・運搬)ごとにかかった時間を一覧にして、どこで滞っていたかを見つける、というイメージ。"}, "gcp-pcde-c-q37": {"point": "JSONログの重大度とトレース相関を自動認識させたいなら、決まったフィールド名severityとlogging.googleapis.com/traceを使う。levelなど自己流の名前では認識されない。", "eg": "宅配便の伝票で『お届け先』という決まった欄に書かないと配達員には伝わらず、自分だけの呼び方の欄に書いても配送システムには読み取ってもらえない、というイメージ。"}, "gcp-pcde-c-q38": {"point": "各プロジェクトでの閲覧も残しつつ中央にも集約したいなら、組織レベルで非インターセプト型の集約シンクを作る。インターセプト型だと各プロジェクトの閲覧が止まる。", "eg": "テレビの放送を各家庭のテレビ(各プロジェクト)でも見られるままにしながら、放送局の録画サーバー(中央プロジェクト)にも同時に録画しておく、というイメージ。"}, "gcp-pcde-c-q39": {"point": "ログを複製せずにSQLで分析しつつ長期保持もしたいなら、Log AnalyticsのログバケットをBigQueryにリンクする。", "eg": "図書館の蔵書をわざわざ別の場所にコピーせず、そのままオンライン蔵書検索システムから検索できるようにする、というイメージ。"}, "gcp-pcde-c-q40": {"point": "自動化ツールで機械的に処理したい通知はPub/SubかWebhookを使う。人間向けチャネル(メール・Slack・PagerDuty)は書式が安定せず不向き。", "eg": "人間同士の自然な手紙のやり取りは言い回しが毎回変わるが、機械同士がやり取りするAPI通信なら毎回同じ構造で安定して処理できる、というイメージ。"}, "gcp-pcde-c-q41": {"point": "閲覧に加えて解決状況の更新はできるが、削除や通知設定はできない、という中間の権限にしたいならroles/errorreporting.user。", "eg": "病院のカルテで、看護師は経過欄に記入できるが、カルテそのものの破棄や新しい保管ルールの設定は院長にしかできない、という役割分担に近い。"}, "gcp-pcde-c-q42": {"point": "メンテナンス中だけ静かにして自動的に元へ戻したいなら、期間指定のスヌーズを使う。手動での無効化・再有効化はしない。", "eg": "旅行中だけエアコンを『不在モード』にタイマーでセットしておき、指定した日数が過ぎたら自動的に通常運転に戻る、というイメージ。"}, "gcp-pcde-c-q43": {"point": "マシンタイプ推奨にメモリの実態も反映させたいなら、各VMにOps Agentを入れてゲストOS内のメモリ使用率を取得させる。", "eg": "車の外観だけを見て点検した(標準メトリクス)のと、ボンネットを開けてエンジンの中まで診断した(Ops Agentのゲストメトリクス)のとでは、点検の精度がまるで違う、というイメージ。"}, "gcp-pcde-c-q44": {"point": "動かない定常負荷にはリソースベースCUD、複数リージョン・マシンタイプにまたがる変動ワークロードにはフレキシブルCUDを組み合わせる。", "eg": "携帯電話の料金プランで、いつも同じ回線を長期契約すれば安くなる縛りプラン(リソースベースCUD)と、使う場所や機種を自由に変えられる代わりに割引が控えめなプラン(フレキシブルCUD)を、用途によって使い分ける、というイメージ。"}, "gcp-pcde-c-q45": {"point": "スキャン量を減らしたいなら、WHERE句でパーティション列(タイムスタンプ)に絞り込んでパーティションプルーニングを効かせる。LIMITでは減らせない。", "eg": "年賀状を年ごとに分けた引き出し(パーティション)から、探したい年の引き出しだけを開ければよく、全部の引き出しを漁る必要がない、というイメージ。"}, "gcp-pcde-c-q46": {"point": "VM単位でコストを特定したいなら、詳細な使用料金データエクスポート(resourceテーブル)を使う。標準エクスポートにはリソース単位の情報が無い。", "eg": "家計簿アプリで、月の総支出額しか分からないアプリと、どのレシート(どのVM)にいくら使ったかまで記録が残るアプリの違いに近い。"}, "gcp-pcde-c-q47": {"point": "GKE Autopilotでは可観測性(Cloud Monitoring/Logging)は無効化できない固定仕様。コスト削減の相談が来ても『できない』と答える。", "eg": "機内食付きの航空券を買ったら、機内食だけを『要らないので運賃を安くして』と断れないパッケージ運賃のような仕様に近い。"}, "gcp-pcde-c-q48": {"point": "CPU負荷が原因か外部待ちが原因か切り分けたいなら、CPU時間とWall時間を比較する。Wall時間がCPU時間より大幅に長ければ待ちが原因。", "eg": "勉強時間の記録で、実際に問題を解いていた時間(CPU時間)と、机に向かっていた時間全体(Wall時間、休憩や考え込む時間も含む)を比べれば、集中できていたかどうかが分かる、というイメージ。"}, "gcp-pcde-c-q49": {"point": "増えたり減ったりする『今の値』を記録したいならGAUGE。増加し続ける累計値専用のCUMULATIVEは使えない。", "eg": "駐車場の『現在の空き台数』を表示する電光掲示板のように、増えたり減ったりする瞬間の状態を映すのがGAUGEに近い。"}, "gcp-pcde-c-q50": {"point": "四半期に一度しか触らないイメージも継続スキャン対象に残したいなら、30日以内にpull/pushするスケジュールタスクを作る。手動スキャンやタグの付け替えでは代替できない。", "eg": "ジムの会員が3ヶ月来館しないと自動退会になる規約に対して、月1回だけ顔を出す(pull/pushする)ことで会員資格(継続スキャン対象)を維持し続ける、というイメージ。"}, "gcp-pcde-c-q51": {"point": "反復するgcloudコマンドを自然言語で組み立てさせたいならGemini CLI。定型化してスクリプトに落とすかどうかの判断は引き続き人が持つ。", "eg": "料理のレシピを毎回一から考えるのではなく、AIアシスタントに『冷蔵庫にある材料でレシピ案を出して』と頼み、実際に作るかどうかや定番化するかは自分で決める、というイメージ。"}, "gcp-pcde-c-q52": {"point": "MLモデルのカナリア判定は、レイテンシ・エラー率に加えて予測精度などモデル固有のテレメトリも見て判断する。", "eg": "新しい薬を治験するとき、副作用の有無(レイテンシ・エラー率)だけでなく、実際に病気が治っているか(予測精度)も両方確認してから承認する、というイメージ。"}, "gcp-pcde-c-q53": {"point": "LQLの構文が書けなくても、やりたいことを自然言語で伝えてクエリ案を生成させ、内容を確認してから実行する。生成結果をそのまま鵜呑みにはしない。", "eg": "外国語のメニューが読めないとき、店員に『こういう料理が食べたい』と伝えて候補を教えてもらい、実際に頼む前に中身を確認する、というイメージ。"}, "gcp-pcde-c-q54": {"point": "GKEとCompute Engine両方でリソース過剰確保が疑われるなら、まずActive Assistのライトサイジング推奨事項を確認する。対象はCompute Engine限定ではない。", "eg": "家計の無駄遣いを見直すとき、闇雲に節約するのではなく、家計簿アプリが出す『この支出は減らせます』という診断結果を先に確認してから調整する、というイメージ。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pcde-c')
  AND q.explanation_data IS NOT NULL;

-- gcp-pcde-d
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pcde-d-q1": {"point": "サービスアカウントキーを作らずその場限りの認証情報で高権限操作をしたいなら、権限借用(impersonation)。", "eg": "会社の受付で「今から3階の303号室に入りたい」と伝えると、その場限りで使える一時カードが渡され、使い終われば自動で無効になる。誰がいつ入ったかも記録に残る。合鍵そのものを持ち帰らせる必要はない。"}, "gcp-pcde-d-q2": {"point": "権限が実際に使われているかどうかを実績データから判断したいなら、IAM Recommender。", "eg": "ジムの会員証で、90日間入館履歴がない会員に自動で「休会しませんか」という案内が届く仕組み。人が名簿を見て思い出すのではなく、実際の入退館記録から機械的に判断される。"}, "gcp-pcde-d-q3": {"point": "複数チームが同じような構成をゼロから書いて品質がばらつくなら、審査済みの共有モジュール化で標準化する。", "eg": "文房具を各部署が思い思いに買うと品質も値段もバラバラになるが、総務が審査済みのカタログ(共有モジュール)から選ばせれば、品質が揃い、カタログの改訂だけで全部署に新しい基準が行き渡る。"}, "gcp-pcde-d-q4": {"point": "正しい権限を持つ内部者によるデータの持ち出しを防ぎたいなら、VPC Service Controls。", "eg": "社員証で入退室できるオフィスでも、出口には別途、荷物検査ゲートがある。正社員でも許可されていない書類は外へ持ち出せない。身分証の確認(IAM)と、持ち出しの検査(VPC Service Controls)は別の仕組み。"}, "gcp-pcde-d-q5": {"point": "障害の影響範囲・課金・クォータをまとめて分離したいなら、プロジェクト単位で分ける。", "eg": "集合住宅の各部屋(Namespace)は壁で仕切られていても、電気のブレーカーや水道の元栓(クラスタのクォータ・リソース)は共用のまま。本当に独立させたいなら別の一戸建て(プロジェクト)にする。"}, "gcp-pcde-d-q6": {"point": "IAM条件や組織ポリシーと連動させたいなら、タグ。ラベルは分類・集計用でポリシー条件には使えない。", "eg": "駐車場で、正式な入庫チケット(タグ)はゲートの開閉判定に使われるが、車に貼るだけの部署ステッカー(ラベル)はどの部署の車か分類するためのもので、ゲートはステッカーを読み取らない。"}, "gcp-pcde-d-q7": {"point": "VPNを配らずGoogleアカウントとIAMだけで社外からのアクセスを制御したいなら、IAP。", "eg": "マンションの入口に守衛を置いて、来訪者一人ひとりの身分証と訪問先を確認してから通す方式。住人全員に合鍵を配って建物ごと信頼する方式(VPN)とは発想そのものが違う。"}, "gcp-pcde-d-q8": {"point": "Dockerfileを書かずにベストプラクティスに沿ったイメージを自動生成したいなら、Cloud Native Buildpacks。", "eg": "洋服のオーダーメイド(Dockerfile手書き)は仕立て屋の腕前次第で品質が変わるが、体型を伝えるだけで標準化された工程が仕立ててくれるオーダーシステム(Buildpacks)なら、誰が頼んでも一定の品質に仕上がる。"}, "gcp-pcde-d-q9": {"point": "同じイメージかどうかを確実に検証したいなら、付け替え可能なタグではなく内容そのものを表すダイジェストで突き合わせる。", "eg": "紙幣の額面(タグ)は同じでも、偽造でないかは製造番号やすかし(ダイジェストに相当する内容そのもの)を見て初めて確実に分かる。額面だけでは中身が同じ紙幣かは保証されない。"}, "gcp-pcde-d-q10": {"point": "コードのデプロイと機能の公開タイミングを分けたいなら、フィーチャーフラグ。", "eg": "テレビ番組の収録(デプロイ)と放送(機能公開)は別の日程で行われる。収録済みでも放送スイッチを押すまで視聴者には届かない。"}, "gcp-pcde-d-q11": {"point": "同じコミットから毎回同じ依存関係を再現し改ざんを防ぎたいなら、ロックファイルをコミットする。", "eg": "同じ製品番号だけを指定して注文すると、メーカーの在庫が変わってうっかり別ロットが届くことがある。品番だけでなく製造ロット番号(ハッシュ)まで指定して発注すれば、毎回同じものが届く。"}, "gcp-pcde-d-q12": {"point": "準備が整うまでServiceのロードバランシング対象から外したいなら、readinessProbe。生存確認のlivenessProbeとは目的が別。", "eg": "新人スタッフの研修期間中は接客に立たせない(readiness)のと、勤務中に体調不良で倒れていないか見回る(liveness)のは、チェックする目的もタイミングもまったく違う。"}, "gcp-pcde-d-q13": {"point": "ビルド直後の早期検知でパイプラインを止めたいなら、CI内にスキャンを組み込む。デプロイ時の関門(Binary Authorization)とは止めるタイミングが違う。", "eg": "料理を提供する直前の最終チェック(デプロイ時の門番)だけでなく、食材を仕入れた直後にも鮮度をチェックする(ビルド直後のスキャン)方が、傷んだ食材が調理工程の奥まで進む前に弾ける。"}, "gcp-pcde-d-q14": {"point": "CI/CDの実行主体には、個人アカウントの使い回しではなく最小権限の専用サービスアカウントを用意する。", "eg": "警備員の巡回には専用の巡回用マスターキー(サービスアカウント)を発行し、必要な部屋だけ開けられるようにする。社員個人のカードを使い回すと、その社員が退職した瞬間に巡回自体ができなくなる。"}, "gcp-pcde-d-q15": {"point": "サプライチェーンの多層防御は、ビルド時のスキャンとデプロイ時の署名検証(Binary Authorization)を両方併用する。片方を削ると必ず片方の穴が残る。", "eg": "家の防犯は玄関の鍵(スキャン)だけでなく窓の鍵(Binary Authorization)も両方かけて初めて効果がある。役割が重複しているからと片方を外せば、外した方から侵入される。"}, "gcp-pcde-d-q16": {"point": "サードパーティのビルダーイメージを不正な差し替えから守りたいなら、自組織のリポジトリへミラーリングしてダイジェストで固定参照する。", "eg": "海外の部品を毎回現地業者から直接仕入れる(パブリックレジストリを都度参照)のではなく、一度検品して自社倉庫に受け入れ、シリアル番号(ダイジェスト)で管理する。以後は倉庫にある検品済みの部品だけを使う。"}, "gcp-pcde-d-q17": {"point": "GKE以外の環境にもCloud Deployの標準ワークフロー(承認・プロモーション・履歴)を適用したいなら、カスタムターゲット。", "eg": "宅配便の会社が、トラック配送だけでなく船便や海外配送にも対応する専用ドライバー(カスタムターゲットのデプロイヤーロジック)を追加すれば、伝票発行や追跡といった共通の配送管理システムはそのまま使い続けられる。"}, "gcp-pcde-d-q18": {"point": "モノレポで変更されたサービスだけをビルドしたいなら、トリガーのパスフィルタで発火自体を絞る。", "eg": "アパートの一室で水漏れがあったとき、その部屋だけ修理業者を呼べば済む。アパート全棟(全サービス)の点検を毎回呼ぶ必要はない。"}, "gcp-pcde-d-q19": {"point": "パイプライン自体の所要時間・成功率を継続的に可視化したいなら、Cloud Buildの結果をCloud Monitoringへ連携する。", "eg": "毎日の通勤時間を記録せずに「最近遅くなった気がする」と感覚だけで判断するより、実際に時間を測って記録していけば、いつから遅くなったか、どの区間が原因かが分かる。"}, "gcp-pcde-d-q20": {"point": "本番ロールアウト失敗時に人を待たず自動で前の安定版へ戻したいなら、automaticRollbackを構成する。", "eg": "自転車の補助輪のように、バランスを崩した瞬間に自動で支えてくれる仕組みがあれば、転んでから誰かが助けに来るのを待つ必要がない。"}, "gcp-pcde-d-q21": {"point": "改ざん不可能な証跡が要るなら、Cloud Audit Logsで記録し、さらに保持ポリシー付きのロック済みバケットへ出す。両方揃って初めて『誰も消せない記録』になる。", "eg": "契約書を作成しただけ(記録)では、後から誰かが書き換えられてしまう。公証役場に預けて封をする(ロック済み保持)ことで、初めて誰にも改ざんできない証拠になる。"}, "gcp-pcde-d-q22": {"point": "バッチ処理のSLIは応答速度(レイテンシ)ではなく、データがどれだけ新しいか(新鮮さ)で測る。", "eg": "冷蔵庫の牛乳は、注いでから飲むまでの速さではなく、賞味期限までどれだけ余裕があるか(新鮮さ)で価値が決まる。"}, "gcp-pcde-d-q23": {"point": "『動いているか』と『正しく動いているか』は別軸。中身の正しさを測りたいなら、正確性のSLIを別途追加する。", "eg": "自動販売機がちゃんと動作して何か商品を出しても(可用性は問題なし)、頼んだのと違う商品が出てきたら(不正確)、お客さんにとっては困った結果になる。"}, "gcp-pcde-d-q24": {"point": "エラーバジェット枯渇時の対応で迷わないためには、発生前に対応方針を文書化して合意しておく。", "eg": "保険の契約は、事故が起きてから補償内容を話し合うのではなく、契約時にあらかじめ条件を決めておくから、いざという時にもめずに済む。"}, "gcp-pcde-d-q25": {"point": "カスケード障害を防ぐ設計は、タイムアウトで無限待ちを止めることと、依存先ごとにリソースプールを分離すること(バルクヘッド)の組み合わせ。", "eg": "レストランの厨房で、1つのコンロが焦げ付いても、コンロごとに担当の調理器具や食材を分けておけば、他のコンロの料理まで巻き込まれずに済む。待たされ続ける客を出さないよう、注文にも制限時間を設ける。"}, "gcp-pcde-d-q26": {"point": "過負荷時に優先度の低いリクエストを選んで捨て、重要なリクエストの処理能力を守りたいなら、ロードシェディング。", "eg": "満員の救急外来で、軽症患者を先に待合室で待たせて、重症患者(優先度の高いリクエスト)の処置を優先するトリアージの考え方。"}, "gcp-pcde-d-q27": {"point": "リトライの雪だるま(リトライストーム)を防ぐには、サーキットブレーカーで試行自体を止め、指数バックオフとジッターでタイミングをずらす。", "eg": "コンサート会場の入場が一時的に止まったとき、みんなが同時に入口へ殺到すると将棋倒しになる。係員が一旦入場を止め、再開後も少しずつ間隔をあけて誘導するから混乱が起きない。"}, "gcp-pcde-d-q28": {"point": "読み取り専用クエリが多くプライマリの負荷が高いなら、リードレプリカへ読み取りを振り分ける。", "eg": "人気ラーメン店で、注文を受ける厨房(書き込み)と、出来上がった料理を運ぶスタッフ(読み取り)が同じ1人だと詰まる。運ぶ専門のスタッフを増やせば、厨房は調理に専念できる。"}, "gcp-pcde-d-q29": {"point": "ポストモーテムの改善を実際に進めたいなら、担当者と期限を明記し通常のスプリント作業として追跡する。", "eg": "会議の議事録に「検討する」とだけ書いても誰も動かないが、「来週金曜までに担当者が確認する」と書けば実際に進む。"}, "gcp-pcde-d-q30": {"point": "代替のない直列依存では、自サービスの可用性は依存先の可用性(SLA・実績)を理論上超えられない。", "eg": "どんなに腕の良いシェフ(自サービス)でも、仕入れる魚(依存先)が傷んでいれば、素材の質を超えて美味しい料理は作れない。"}, "gcp-pcde-d-q31": {"point": "オンコールの初動対応力を上げたいなら、実践的な模擬演習(ゲームデー)で体で覚えさせる。マニュアルを厚くするだけでは対応速度は上がらない。", "eg": "水泳は教本を読むだけでは泳げるようにならず、実際にプールに入って練習して初めて体が覚える。"}, "gcp-pcde-d-q32": {"point": "SLO運用の立ち上げでは、ユーザーの重要な利用シーンからSLIを選び、初期のSLOは仮値として実績を見ながら反復的に見直す。", "eg": "新しいダイエット計画を立てるとき、最初から完璧な目標体重を決めるより、まず自分が何に困っているか(食べ過ぎ、運動不足)を洗い出し、目標は様子を見ながら微調整していく方がうまくいく。"}, "gcp-pcde-d-q33": {"point": "実行されるべき処理が一度も走らなかった『沈黙』を検知したいなら、正常終了ログが一定時間更新されないことを見張る不在アラートを設定する。", "eg": "毎朝届くはずの宅配便が来なかったとき、荷物が壊れていた(エラー)なら気づけるが、そもそも配達自体がなかった場合は、『届いていないこと』に自分で気づく仕掛けが別途必要。"}, "gcp-pcde-d-q34": {"point": "サービス横断で検索・集計したいなら、自由形式のテキストログをJSONの構造化ログ+共通フィールドに統一する。", "eg": "各国がバラバラの単位(インチ、尺、メートル)で長さを記録すると比較できないが、全部メートル法(共通フィールド)に統一すれば、世界中のデータを機械的に比較・集計できる。"}, "gcp-pcde-d-q35": {"point": "アラートが復旧したことも知らせたいなら、通知設定でクローズ(復旧)時の通知を有効にする。", "eg": "台風情報は『発生しました』という速報だけでなく、『温帯低気圧に変わりました』という解除情報も流れて初めて、今どういう状況か分かる。"}, "gcp-pcde-d-q36": {"point": "オンコールが手順を探さず参照できるようにしたいなら、アラート通知そのものにランブックへのリンクを添付する。", "eg": "薬の説明書を薬局の棚に別途保管するより、薬のパッケージに直接貼っておけば、飲むときにすぐ用法用量を確認できる。"}, "gcp-pcde-d-q37": {"point": "使われていないカスタム指標を洗い出すには、名前や作成日ではなく、書き込みと読み取り(クエリ)の実績を確認する。", "eg": "サブスクリプションサービスの整理で、契約した日付や名前ではなく、実際に今月ログインして使ったかどうかで解約候補を判断するのが確実。"}, "gcp-pcde-d-q38": {"point": "経営層にも分かりやすくSLOとエラーバジェットの状況を継続的に共有したいなら、Cloud MonitoringのSLOダッシュボードを使う。", "eg": "工場の稼働率を経営会議で報告するとき、機械の詳細な稼働ログをそのまま見せるより、『今月の生産目標達成率』という1つの数字にまとめた方が誰にでも伝わる。"}, "gcp-pcde-d-q39": {"point": "アプリコードを変えずにCPU・メモリとstdoutログを集めたいなら、GKEの組み込み監視連携とデフォルトロギングエージェントに任せる。", "eg": "新しいオフィスビルに入居すると、最初から備え付けの電力メーターや郵便受けがあり、テナントが自分で工事しなくても最初から使える。"}, "gcp-pcde-d-q40": {"point": "機密情報がログに出た時点で機械的に検知したいなら、Sensitive Data Protectionのログ検査機能を使う。人の注意力に頼らない。", "eg": "校閲を人間の目視だけに頼ると誤字を見逃すことがあるが、スペルチェッカーのような機械的な検査を通せば、既知のパターンのミスを確実に拾える。"}, "gcp-pcde-d-q41": {"point": "一瞬だけ閾値を超えてすぐ戻るノイズでの誤発報を抑えたいなら、超過が一定時間続いた場合にのみ発報する持続時間(duration)を設定する。", "eg": "エレベーターの重量センサーは、人が一瞬飛び跳ねただけでは警報を鳴らさず、一定時間定員超過の状態が続いて初めて警告する設計になっている。"}, "gcp-pcde-d-q42": {"point": "複数プロジェクトのコストをSQLで柔軟に分析したいなら、課金データのBigQueryエクスポートを有効にする。", "eg": "レシートの写真を眺めるだけでは支出の傾向は分析しづらいが、家計簿アプリに取引データとして取り込めば、費目別・月別に自由に集計できる。"}, "gcp-pcde-d-q43": {"point": "CPU・メモリに余裕があるのにPendingなら、リソース不足ではなく配置制約(nodeSelector/affinity/taint-toleration)の不一致をまず疑う。", "eg": "レストランの席は空いているのに案内されないとき、実は『予約限定席』のような条件があって、その条件に合わないと座れないことがある。空席の数ではなく条件の一致を確認する。"}, "gcp-pcde-d-q44": {"point": "リクエストに依存しない重い初期化処理は、リクエストハンドラの外(起動時)へ出して1回だけ実行し、インスタンスの生存期間中使い回す。", "eg": "会議のたびにプロジェクターの接続設定をゼロからやり直すのではなく、朝一番に一度セットしておけば、その日の残りの会議では設定を使い回せる。"}, "gcp-pcde-d-q45": {"point": "特定Podの過剰なログ出力がディスクI/O競合の原因なら、まずそのPodの出力を見直す。ノードを増やしても同居している限り解消しない。", "eg": "アパートの1部屋が洗濯機を何十回も回して共用の排水管が詰まっているとき、建物を増築しても、その部屋が同じ排水管を使い続ける限り根本解決にならない。"}, "gcp-pcde-d-q46": {"point": "Cloud Runの課金はインスタンスに割り当てたCPU/メモリの量で決まる。実際の並列度が低いなら、割り当てそのものを縮小するのが直接的な節約。", "eg": "3人家族なのに毎回5人乗りの大型車を借りているなら、実際の乗車人数に合わせて小さい車に変えた方が燃費(コスト)がよくなる。"}, "gcp-pcde-d-q47": {"point": "CPU使用率がボトルネックの実態(I/O待ち)を反映しないなら、キューの長さなどのカスタムメトリクスでHPAをスケーリングする。", "eg": "郵便局の窓口が混んでいるかどうかは、職員の額の汗の量ではなく、実際に並んでいる列の長さを見て判断すべき。"}, "gcp-pcde-d-q48": {"point": "障害調査を効率化するなら、まず直近の変更との相関を疑い、可観測性の3本柱を全体像(メトリクス)から詳細(ログ・トレース)へと段階的に絞り込む。", "eg": "車の調子が悪いとき、まず『最近何か整備や部品交換をしたか』を思い出し、次にダッシュボードの警告灯(全体像)を見て、最後にエンジンを開けて詳しく調べる、という順番で原因を絞り込む。"}, "gcp-pcde-d-q49": {"point": "Recommenderの『アイドル』という推奨をそのまま実行せず、そのディスクがバックアップ・DR用途で使われていないかを人が確認してから対応する。", "eg": "空き家に見える家でも、実は年に数回しか使わない別荘かもしれない。取り壊す前に本当に不要か持ち主に確認する必要がある。"}, "gcp-pcde-d-q50": {"point": "特定地域だけレイテンシが高いなら、その地域だけの経路・構成差分を洗い出すのが最初の一手。全体への増強やSLO緩和では原因を教えてくれない。", "eg": "クラス全体ではなく特定の生徒だけテストの点数が低いとき、まずその生徒だけ教材や授業の受け方に違いがないかを確認するのが先で、クラス全体の授業時間を増やしても的外れなことがある。"}, "gcp-pcde-d-q51": {"point": "開発者が個別セットアップしなくてもAI支援を使えるようにしたいなら、Gemini Code AssistをCloud Workstationsのカスタムイメージへあらかじめ組み込む。", "eg": "新入社員に配るノートPCに、あらかじめ必要なソフトを全部インストールしておけば、初日から個別にセットアップさせずに仕事を始められる。"}, "gcp-pcde-d-q52": {"point": "本番デプロイしたMLモデルがどのバージョンか追跡したいなら、学習済みモデルをバージョン管理された成果物としてArtifact Registryへ登録する。", "eg": "美術館が絵画を展示するとき、どの作品がいつ誰の作で搬入されたかを台帳に記録しておくから、後で来歴を確認できる。記録せず飾るだけでは、後から由来を追えなくなる。"}, "gcp-pcde-d-q53": {"point": "PromQLをゼロから書く手間を省きたいなら、Gemini Cloud Assistに自然言語でクエリの下書きを作らせ、意図通りか確認してから使う。", "eg": "外国語のメニューを翻訳アプリで下訳してもらい、注文する前に意味が合っているか自分でも確認してから店員に伝える。"}, "gcp-pcde-d-q54": {"point": "トレースIDと構造化ログの相関付けを効率化したいなら、AIに対応関係の見当をつけさせ、そこから先の詳細確認は人が行う。", "eg": "刑事ドラマで、AIが防犯カメラ映像から容疑者らしき人物を絞り込んでくれても、最終的に本人と特定するのは刑事が現場で裏を取る作業。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pcde-d')
  AND q.explanation_data IS NOT NULL;

-- gcp-pcde-e
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pcde-e-q1": {"point": "境界を通す条件に「どんな端末から来たか」まで含めたいなら、Access Context Managerでアクセスレベルを定義してVPC Service Controlsの境界へ適用する。IPやログイン可否だけでは端末の状態は条件にできない。", "eg": "たとえるなら、会員制ジムの入館ゲートが会員証(認証)だけでなく、指定のシューズを履いているか(端末の状態)まで確認してから開くイメージ。"}, "gcp-pcde-e-q2": {"point": "組織全体を継続的に・一元的に見張りたいならSecurity Command Center。個別の自己申告や一部分だけを見る仕組みでは範囲が足りない。", "eg": "たとえるなら、各家庭の自主的な戸締まり確認に頼るのではなく、街全体を映す監視カメラのネットワークをまとめて運用するイメージ。"}, "gcp-pcde-e-q3": {"point": "「ある時点で何が存在していたか」を後から証明したいならCloud Asset Inventory。操作ログは「誰が何をしたか」の記録であって、その時点の状態そのものではない。", "eg": "たとえるなら、家計簿(操作の記録)ではなく、毎月の資産残高を自動でスナップショットしてくれる通帳のようなもの。"}, "gcp-pcde-e-q4": {"point": "規制対応の制御を「個別に調べて組み合わせる」のではなく「まとめて適用したい」ならAssured Workloads。", "eg": "たとえるなら、部品を1つずつ選んで自作PCを組む代わりに、用途別にあらかじめ構成済みのモデルを買うイメージ。"}, "gcp-pcde-e-q5": {"point": "平時は絞る・緊急時だけ即座に昇格・使ったら必ず記録が残る、の3点セットが揃っているかがbreak-glass設計の決め手。恒久付与や人への依頼、長命なキーはどれかが欠ける。", "eg": "たとえるなら、非常階段の鍵は普段はかかっているが、非常時はすぐ開けられて、開けた瞬間に警備室へ通知が飛ぶ仕組み。"}, "gcp-pcde-e-q6": {"point": "コード化した「はず」を信じず、実際とのズレを機械的に確認したいなら、terraform planの定期実行によるドリフト検知。", "eg": "たとえるなら、家計簿アプリと銀行口座の残高を毎晩自動で突き合わせて、記録漏れがないか確認する仕組み。"}, "gcp-pcde-e-q7": {"point": "「実際の消費量に基づいて」チームごとの請求根拠を示したいなら、GKEのコストアロケーション。頭割りや上限値(ResourceQuota)は実測ではない。", "eg": "たとえるなら、シェアハウスの電気代をスマートメーターで部屋ごとに実測して割り勘するイメージ。人数割りではない。"}, "gcp-pcde-e-q8": {"point": "「保持条件を宣言するだけで自動的に回る」ならクリーンアップポリシー。自作スクリプトは保守対象を増やし、Cloud Storageのライフサイクルはレジストリには効かない。", "eg": "たとえるなら、賞味期限切れの食品を自動で教えてくれる冷蔵庫。毎晩自分でチェックするスクリプトを書く必要がない。"}, "gcp-pcde-e-q9": {"point": "「含まれる部品の一覧を事前に網羅的に」欲しいならSBOM。脆弱性スキャン結果は見つかったものだけ、ロックファイルは一部のエコシステムだけしか映さない。", "eg": "たとえるなら、食品の原材料表示があれば、あるアレルギー物質が後から問題になっても、どの商品が該当するかすぐ調べられる。"}, "gcp-pcde-e-q10": {"point": "「指標が悪化したら自動で止める」を実現したいならCloud Deployのカナリア分析とCloud Monitoringの連携。人の目視や承認では判定と停止が指標に直結しない。", "eg": "たとえるなら、体調モニターが異常値を検知したら自動的に投薬を中止する仕組み。医師が四六時中張り付いて見る必要がない。"}, "gcp-pcde-e-q11": {"point": "本番イメージに「実行に不要なものが残っていないか」が決め手。マルチステージビルドの最終ステージはビルドツールやテストファイルを持ち込まない最小構成にする。", "eg": "たとえるなら、厨房で使った鍋やまな板はお客様のテーブルには並べない。完成した料理だけを出すイメージ。"}, "gcp-pcde-e-q12": {"point": "CI結果が「開発者が既に見ている画面(プルリクエスト)」に自動で返るかが決め手。GitHub App連携ならステータスチェックとして自動表示される。", "eg": "たとえるなら、答案を提出したその場で採点結果が自動表示されるテスト。先生が別室で口頭発表するのでは遅い。"}, "gcp-pcde-e-q13": {"point": "コンテナ以外の成果物(テスト結果・カバレッジ)を後から参照したいなら、artifacts指定でCloud Storageへ自動保存する。ログは保持期間で消え、イメージへの同梱は肥大化を招く。", "eg": "たとえるなら、工場の完成品だけでなく検品記録も倉庫に保管しておけば、後から品質の推移を確認できる。"}, "gcp-pcde-e-q14": {"point": "パイプラインの権限設計は「侵害されたときの被害範囲を小さくできるか」で選ぶ。最小権限とステップごとの権限分離がその2本柱で、単一の強い権限に統一する発想は逆効果。", "eg": "たとえるなら、工場のライン作業者には持ち場ごとの鍵だけを渡し、倉庫の総合鍵は誰にも持たせない防犯設計。"}, "gcp-pcde-e-q15": {"point": "ゼロダウンタイムの決め手は「終了処理をアプリ自身が実装しているか」。猶予時間を延ばす、固定の待ち時間を入れるといった設定だけの調整はごまかしにすぎない。", "eg": "たとえるなら、閉店の合図が出たら新しいお客は断りつつ、今対応中のお客の会計は最後まで済ませてから店を閉めるイメージ。"}, "gcp-pcde-e-q16": {"point": "アーティファクト・承認記録・ロールアウト履歴を「ひとまとめに」束ねる単位を聞かれたらリリース。ロールアウトは適用の実行、ターゲットはデプロイ先、パイプラインは経路にすぎない。", "eg": "たとえるなら、1つの出荷ロットに内容物・検品記録・出荷承認印がすべて紐づいた出荷伝票が発行されるイメージ。"}, "gcp-pcde-e-q17": {"point": "毎回作り直されるビルドワーカーをまたいで「前回の結果を持ち越したい」なら、Cloud Storageのような外部へキャッシュを保存・復元する構成にする。マシンを強くしても取得量自体は変わらない。", "eg": "たとえるなら、毎回買い出しから始めるのではなく、前回買った食材の残りを冷蔵庫に保管しておいて、次の調理で使い回すイメージ。"}, "gcp-pcde-e-q18": {"point": "「特定の時間帯だけデプロイを許可」したいなら、Cloud Deploy自体ではなくデプロイを起動するトリガー側で時間帯を制御する。承認や有効・無効の切り替えは人の判断や運用ミスに弱い。", "eg": "たとえるなら、銀行の窓口は営業時間内しか開けられないようにシステム側で決めておく。窓口担当者の自己判断には任せない。"}, "gcp-pcde-e-q19": {"point": "パイプラインの障害耐性は「再実行しても壊れないか(冪等性)」と「一時的な失敗を拾えるか(適切なリトライ)」の2本柱で決まる。再実行の全面禁止や無制限の待機はどちらも脆さを増やす。", "eg": "たとえるなら、エレベーターのボタンは何度押しても同じ階に行くだけ(冪等)。反応しなければもう一度押せばいい(リトライ)。"}, "gcp-pcde-e-q20": {"point": "承認の対象は「ソースではなく実際に適用される生成物」かどうかが決め手。base/overlayの合成結果=レンダリング済みマニフェストを見て承認する。", "eg": "たとえるなら、レシピの材料表だけを見て承認するのではなく、実際に出来上がった完成品を試食してから承認するイメージ。"}, "gcp-pcde-e-q21": {"point": "コンフリクトを小さく保ちたいなら「main側から離れている期間を短くする」こと。頻繁にmainの変更を取り込む習慣がその実践。", "eg": "たとえるなら、川の増水はこまめに水位を確認して少しずつ調整する方が、放置して一気に堤防を作り直すより安全。"}, "gcp-pcde-e-q22": {"point": "「復旧までの時間の許容」を聞かれたらRTO、「データ損失の許容範囲」を聞かれたらRPO。この2つの軸を混同しないことが決め手。", "eg": "たとえるなら、停電がいつ復旧してほしいか(RTO)と、停電前のどの時点までのデータが戻れば納得できるか(RPO)は別の質問。"}, "gcp-pcde-e-q23": {"point": "リージョン全体の障害でRTOを数分にしたいなら、対策も同じ範囲(リージョンをまたぐ)で用意する必要がある。ゾーン分散やバックアップ頻度の向上ではその範囲に届かない。", "eg": "たとえるなら、1つの街が丸ごと停電したら、その街の中でどう頑張っても復旧しない。別の街への切り替え体制があって初めて短時間復旧が可能になる。"}, "gcp-pcde-e-q24": {"point": "トイルが増え続けているなら、割合に上限の目安を決めて超過分を自動化に投資する、がSREの基本方針。人数を増やすだけや放置では総量が減らない。", "eg": "たとえるなら、皿洗いに一日の半分以上を取られると新しい料理を考える時間がなくなる。上限を決めて食洗機の導入に投資する発想。"}, "gcp-pcde-e-q25": {"point": "インシデントの初動を早めたいなら「起きてから調べる」のではなく「平時から地図を用意しておく」こと。依存関係マップの平時の整備が決め手。", "eg": "たとえるなら、火事が起きてから配管図を探し回るのではなく、平時から壁に貼ってある配管図をすぐ見られる状態にしておくイメージ。"}, "gcp-pcde-e-q26": {"point": "サーキットブレーカーの回復判定は「段階を踏んで実際の応答を試したか(半開状態)」が決め手。経過時間だけで一斉に再開する、あるいは二度と再開しないのはどちらも極端で危険。", "eg": "たとえるなら、営業再開時にいきなり全員を入れるのではなく、まず数人だけ試験的に入れてみて問題なければ本格営業を再開するイメージ。"}, "gcp-pcde-e-q27": {"point": "オンコールの偏りを解消したいなら「担当できる人を増やして分担する」が決め手。報酬を増やす、計測をやめるといった対応は負荷そのものを減らさない。", "eg": "たとえるなら、リレーで1人だけ何区間も走らされ続ければいずれ疲労で走れなくなる。走者を増やし区間を分担してこそチームがゴールし続けられる。"}, "gcp-pcde-e-q28": {"point": "サービスレビューの中身を聞かれたら「信頼性を組織の優先順位付けに翻訳する場」。技術詳細だけ、財務指標だけ、個人評価だけに矮小化しない。", "eg": "たとえるなら、健康診断の総合レビューは個々の検査項目の深掘りではなく、全体の健康状態を俯瞰して次の生活習慣改善の方針を決める場。"}, "gcp-pcde-e-q29": {"point": "スケールアウトの閾値は「新インスタンスが立ち上がるまでの遅れ(リードタイム)」を見込んで、負荷が限界に達する前の早めの水準に設定する。", "eg": "たとえるなら、お店が満席になってから増員の電話をかけると、応援が来る間ずっと行列ができる。混み始めた時点で早めに呼んでおく。"}, "gcp-pcde-e-q30": {"point": "バックアップが「本当に使えるか」は取得ログではなく、実際に復元してみて初めて分かる。定期的な復元テスト(リストアドリル)が決め手。", "eg": "たとえるなら、消火器は設置しているだけでは安心できない。実際に試射して噴射できるか確認して初めて本当に頼れる装備といえる。"}, "gcp-pcde-e-q31": {"point": "重大度分類の目的は「対応体制を一貫させる基準」と「関係者間の共通言語」の2つ。担当者個人の評価や形式的な儀式ではない。", "eg": "たとえるなら、病院のトリアージの色分けは、どの患者から診るかと、どの科をどれだけ呼ぶかを一瞬で共有するための仕組み。医師個人の腕前評価ではない。"}, "gcp-pcde-e-q32": {"point": "「本番投入前に運用可能かを体系立てて確認する」基準を指すならProduction Readiness Review。開発側の完了条件(Definition of Done)とは別物。", "eg": "たとえるなら、飛行機の就航前審査はエンジン性能だけでなく、整備体制や緊急時のマニュアルまで含めて総合的にチェックする。"}, "gcp-pcde-e-q33": {"point": "「両方そろって初めて発報」させたいなら、条件をANDで結ぶコンバイナを設定する。OR結合や別々のポリシーでは片方だけで発報してしまう。", "eg": "たとえるなら、入場に身分証とチケットの両方が必要なイベントで、どちらか一方だけでは入れない設計にするイメージ。"}, "gcp-pcde-e-q34": {"point": "後から任意のパーセンタイルを見たいなら、値をヒストグラムとして残す分布型指標を使う。平均やカウンタでは分布の形が失われる。", "eg": "たとえるなら、テストの平均点だけ覚えておくと後から上位10%だけ知りたくても計算できない。全員の点数の分布を記録しておけば自由に切り出せる。"}, "gcp-pcde-e-q35": {"point": "特定地域だけの障害まで検知したいなら、稼働時間チェックのチェッカーを複数リージョンから実行する。1か所からの監視や頻度アップでは見えない範囲が残る。", "eg": "たとえるなら、1か所の展望台からだけ見張っていると、その死角にある裏路地の火事には気づけない。複数の展望台から同時に見張る。"}, "gcp-pcde-e-q36": {"point": "メトリクスのスパイクから原因のトレースへ「直接」飛びたいなら、エグゼンプラー。共通ラベルでの絞り込みでは条件に合う集合しか返らない。", "eg": "たとえるなら、売上グラフの急上昇した1点に、その時間帯の代表的な取引伝票へのリンクが直接貼ってあるイメージ。"}, "gcp-pcde-e-q37": {"point": "ログをSQLで柔軟に結合・集計したいなら、Log Analyticsでの直接クエリか、BigQueryへのエクスポートのどちらか。ログベース指標やCloud Storageへの保管では柔軟な分析ができない。", "eg": "たとえるなら、倉庫の在庫をその場でSQL検索できるようにするか、分析専用の建物に移してから調べるか、2つのやり方があるイメージ。"}, "gcp-pcde-e-q38": {"point": "通知チャネルの検証の目的を聞かれたら「実際に届く宛先かを事前に確かめること」。法律上の義務やスパム防止は主目的ではない。", "eg": "たとえるなら、避難訓練の緊急連絡網に登録した電話番号が実は間違っていた、という事態を防ぐために事前に試験的にかけてみるイメージ。"}, "gcp-pcde-e-q39": {"point": "ログ・メトリクス・トレースを横断的に紐づけたいなら、送信時点で組織共通のラベル・命名規則を決めておく。後付けの変換や格納先の統一だけでは揃わない。", "eg": "たとえるなら、部署ごとに違う呼び方で同じ商品を管理していると在庫を横断的に把握できない。全社共通の商品コードを使えば自動的に突き合わせられる。"}, "gcp-pcde-e-q40": {"point": "まだ閾値未満でも悪化傾向が見えているなら、閾値到達を待たずに先手で原因調査を始める。アラートは対応の開始点ではなく最終防衛線。", "eg": "たとえるなら、健康診断の数値がまだ基準値内でも年々じわじわ悪化しているなら、基準値を超えるのを待たずに生活習慣を見直し始める。"}, "gcp-pcde-e-q41": {"point": "可観測性コストを削るなら、まず内訳を分析して重要度に応じた優先順位をつける。一律削減や上位から機械的に止めるのは重要な監視まで削るリスクがある。", "eg": "たとえるなら、家計の支出を減らしたいとき、内訳を見ずに全項目を一律半額にすると生活に支障が出る費目まで削ってしまう。"}, "gcp-pcde-e-q42": {"point": "ダッシュボードも「コードでレビューを経て変更する」対象にしたいなら、JSON/Terraformでコード化してGitで管理する。コンソールでの直接編集やその書き出しは正本にならない。", "eg": "たとえるなら、アプリのコードを本番サーバーで直接書き換えないのと同じで、ダッシュボードの定義もGitで管理してからデプロイするイメージ。"}, "gcp-pcde-e-q43": {"point": "勘で決めていたrequests/limitsを直したいなら、まず推奨モードで実際の使用量に基づく提案を確認してから反映する。いきなり自動適用モードで本番導入するのは検証を飛ばした危うい進め方。", "eg": "たとえるなら、洋服のサイズを勘で買う代わりに、まず採寸だけしてもらいサイズ表を見てから購入を決めるイメージ。"}, "gcp-pcde-e-q44": {"point": "Spot VMの中断に安全に対応したいなら、プリエンプション通知を受け取るハンドラを実装し、猶予時間内に処理状態を保存してから終了する。", "eg": "たとえるなら、閉店30分前の予告放送があれば、レジ締め作業を落ち着いて終わらせてから店を閉められるイメージ。"}, "gcp-pcde-e-q45": {"point": "AutopilotとStandardの違いを聞かれたら「ノード管理をGoogleに委ねるか、自分で細かくチューニングするか」の軸で考える。Autopilotは手軽さと引き換えに自由度を制限する側。", "eg": "たとえるなら、Autopilotは家具付きマンション(管理をお任せ)、Standardは自分で内装を選べる注文住宅(自由にチューニング)。手軽さと自由度はトレードオフの関係。"}, "gcp-pcde-e-q46": {"point": "1クライアントの暴走を止めたいなら、クライアント単位(APIキーやIP等)でのレート制限が決め手。全体一律の制限は正常な利用者も巻き添えにする。", "eg": "たとえるなら、食べ放題で1人が独占しているなら、全体の提供量を減らすより1人あたりの上限を決める方が問題の客だけを的確に抑えられる。"}, "gcp-pcde-e-q47": {"point": "リクエストの合間もCPUを使いたい(常駐処理)なら、CPU常時割り当てに変更する。既定はリクエスト処理中のみCPUが確保される設定。", "eg": "たとえるなら、デフォルトは注文が入った時だけ厨房の火を強める設定。注文の合間の仕込みも続けたいなら常時火をつけておく設定に変える。"}, "gcp-pcde-e-q48": {"point": "1台のノードだけ異常なら、まずそのノード固有の状態(リソース・イベント)を確認する。全ノード共通のアプリコードを疑うのは、他ノードが正常という手がかりと矛盾する。", "eg": "たとえるなら、同じ機種の機械のうち1台だけ調子が悪いなら、全機種共通の設計より先に、その1台固有の故障や汚れを点検するのが自然な順番。"}, "gcp-pcde-e-q49": {"point": "特定プレフィックスへのアクセス集中(ホットスポット)を避けたいなら、オブジェクト名の先頭に分散性のある文字列(ハッシュ等)を付与する設計に見直す。", "eg": "たとえるなら、図書館の同じ棚に人気の本を全部集めると渋滞する。配置番号の頭をバラけさせて複数の棚に分散させれば混雑が緩和される。"}, "gcp-pcde-e-q50": {"point": "即座に落ちるのではなく時間とともにじわじわ悪化するパターンなら、まずメモリリークを疑う。症状の時間的な形が原因の候補を絞り込む手がかりになる。", "eg": "たとえるなら、水槽の水位が蛇口の閉め忘れで少しずつ上がり続けて溢れるように、解放し忘れたメモリが少しずつ溜まっていくイメージ。"}, "gcp-pcde-e-q51": {"point": "AIにコードの下書きを書かせる場面の決め手は「生成後に人がレビューしてから適用するか」。対応言語が限定されるという誤解や、レビューの省略は選ばない。", "eg": "たとえるなら、下書きは秘書に書いてもらっても、判子を押す前に自分で中身を確認してから提出するイメージ。"}, "gcp-pcde-e-q52": {"point": "AI分析とPII保護は別レイヤーの対策。「マスキングを先に済ませてからAIに渡す」のが正しい順序で、AIがマスキング作業そのものを代替するわけではない。", "eg": "たとえるなら、個人情報を黒塗りしてから資料を渡すのは人間側の作業。AIはその後の分析だけを手伝うイメージ。"}, "gcp-pcde-e-q53": {"point": "AIの提案はあくまで検討の「材料」。最終的な閾値はSLOやビジネス影響を踏まえて人が決める、という役割分担が決め手。", "eg": "たとえるなら、天気予報を見て傘を持つかどうかは自分で決める。予報士が最終判断をしてくれるわけではない。"}, "gcp-pcde-e-q54": {"point": "割引の適用漏れを効率的に確認したいなら、まずActive Assistの推奨事項を見る。手作業の全件洗い出しや「自動で全部適用されるはず」という思い込みは非効率・不正確。", "eg": "たとえるなら、健康診断の結果表を先に見てから生活改善を検討する方が、自分で全部の数値を1から測り直すより効率的。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pcde-e')
  AND q.explanation_data IS NOT NULL;

-- gcp-pcde-g
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"gcp-pcde-g-q1": {"point": "共有先を組織外の個人アカウントも含めて機械的に弾きたいなら、ドメイン制限共有。", "eg": "会社の私書箱が、宛先が登録済みの部署でなければ自動的に差し戻すようなもの。うっかり外部の個人宛に出しても、そもそも受け付けてもらえない。"}, "gcp-pcde-g-q2": {"point": "通知の種類ごとに届け先を組織階層で一元管理したいなら、Essential Contacts。", "eg": "住民登録に「火災のときはここへ」「水道トラブルはここへ」と種類別の連絡先を届け出ておくようなもの。種類ごとに決まった相手へ自動的に届く。"}, "gcp-pcde-g-q3": {"point": "共有VPCで特定のサブネットだけ使わせたいなら、サブネット単位でネットワークユーザーロールを付与する。", "eg": "貸し会議室ビルで、契約した部屋の鍵だけを渡すようなもの。ビル全体の鍵を渡す必要はない。"}, "gcp-pcde-g-q4": {"point": "支払いは一本化しつつ内訳も見たいなら、請求先アカウントは1つにし、内訳はプロジェクトとラベルで分ける。", "eg": "家族カードは1つの口座から引き落とされるが、明細には家族それぞれの利用分が記録される、というイメージ。"}, "gcp-pcde-g-q5": {"point": "属性が変わるたびに自動でメンバーシップを更新したいなら、動的グループ。", "eg": "年齢が上がったら自動で貸出資格の区分が切り替わる会員証のようなもの。窓口の人が毎回手作業で登録し直す必要がない。"}, "gcp-pcde-g-q6": {"point": "Google Cloud内で完結する社内向けTerraformモジュールの版管理レジストリが欲しいなら、Artifact Registry。", "eg": "社内の工具貸出センターのようなもの。各自が勝手に工具のコピーを作らず、貸出センターにある正式な版を借りて使う。"}, "gcp-pcde-g-q7": {"point": "フォルダを移動したら、継承されるポリシーは移動先フォルダのものに切り替わると理解しておく。", "eg": "転校すると転校先の校則に従うことになり、前の学校の校則はもう関係なくなる、というのと同じ。"}, "gcp-pcde-g-q8": {"point": "テスト済みのものを確実に本番へ届けたいなら、ビルドは1回だけにし、その成果物をそのまま昇格させる。", "eg": "完成した1つのケーキをそのまま各会場に配送するのが正解で、会場ごとに材料から作り直すと同じ味になる保証がない。"}, "gcp-pcde-g-q9": {"point": "複数プロジェクトにまたがるパイプラインでは、必要な範囲だけをプロジェクトごとに個別付与する。", "eg": "出張先の各支社で、その支社の会議室だけ使える来客証を発行してもらうイメージ。全支社の社長室の鍵をまとめて渡す必要はない。"}, "gcp-pcde-g-q10": {"point": "マシンスペック不足を疑うなら、まず高性能マシンタイプに変えて試し、その仮説自体を検証する。", "eg": "遅いパソコンで作業が重いと疑うなら、まず性能の良いパソコンに変えてみて速くなるか確かめるのが素直な一手、というだけの話。"}, "gcp-pcde-g-q11": {"point": "サービスメッシュ無しでネイティブに重み付けトラフィック分割をしたいなら、Gateway APIのHTTPRoute。", "eg": "大まかにしか誘導できなかった交差点の交通整理員の代わりに、車線ごとに細かく比率調整できる新しい信号機が導入された、というイメージ。"}, "gcp-pcde-g-q12": {"point": "同一リリースを複数リージョンへ同時に展開したいなら、デリバリーパイプラインの並列フェーズでターゲットをグループ化する。", "eg": "同じ商品を複数の店舗へ一斉に発送する物流センターの仕組みのようなもの。店舗ごとに別々に仕入れさせると、同じ商品である保証がなくなる。"}, "gcp-pcde-g-q13": {"point": "脆弱性の例外を認めるなら、理由・承認者・期限を記録に残し、期限が来たら見直す仕組みをセットにする。", "eg": "工事現場の一時的な立ち入り許可証に、誰が・なぜ・いつまでを明記しておき、期限が来たら更新の要否を確認する、という運用に近い。"}, "gcp-pcde-g-q14": {"point": "テストの実行順序によって結果が揺れるなら、順序を固定するのではなく、毎回データベースをクリーンな状態にリセットする。", "eg": "実験のたびに器具を洗浄してから始めるのと同じ。前の実験の試薬が残ったままでは、何度実験しても結果が安定しない。"}, "gcp-pcde-g-q15": {"point": "クリーンアップは成功時だけでなく、失敗時にも必ず走らせる。", "eg": "料理教室で、うまく作れた日だけ片付けて失敗した日は放置していたら、キッチンはすぐ物であふれる。うまくいってもいかなくても後片付けは必須。"}, "gcp-pcde-g-q16": {"point": "CIからプライベートなパッケージ取得を安全に認証したいなら、長命な鍵を発行せず、サービスアカウントの権限と標準の認証ヘルパーに任せる。", "eg": "社員証をかざすだけで自動的に開く社内資料室のゲートのようなもの。毎回IDとパスワードを紙に書いて見せる必要がない。"}, "gcp-pcde-g-q17": {"point": "ロールバックの完了は、コマンドの成功ではなく、実際の動作確認(スモークテスト)をもって宣言する。", "eg": "避難訓練で「避難完了」の号令が鳴っても、実際に全員が安全な場所にいるか点呼で確かめて初めて訓練終了と言える、というのと同じ。"}, "gcp-pcde-g-q18": {"point": "共有プロジェクトでトリガーごとに権限を絞りたいなら、トリガーごとに専用のサービスアカウントを割り当てる。", "eg": "同じ工場を借りている複数のテナントに、各社の作業場だけ入れる専用の鍵を渡すイメージ。合鍵を全員に配ると、1社の事故が他社の作業場にまで及んでしまう。"}, "gcp-pcde-g-q19": {"point": "観察時間(bake time)を置くのは、たまにしか起きない問題に出会う機会と、判断に足るデータ量の両方を確保するため。", "eg": "新しい健康診断の機械を導入したとき、1回の検査だけで合格とせず、しばらく稼働させて珍しい不具合の有無と十分なデータ量を確認するようなもの。"}, "gcp-pcde-g-q20": {"point": "Config Syncを使っている限り、kubectlでの手動変更は次の同期で元のGit定義に戻されると理解しておく。", "eg": "常に設計図どおりに部屋を保つ管理人がいる家で、勝手に家具を動かしても、次の巡回で元の配置に戻されてしまう、というイメージ。"}, "gcp-pcde-g-q21": {"point": "似た設定を複数のトリガーで使い回すなら、共通部分をテンプレート化し、差分だけをsubstitution変数で表現する。", "eg": "契約書を毎回一から作らず、共通のひな形を用意して名前などの部分だけ空欄にして埋めるようにすれば、修正が一箇所で済む。"}, "gcp-pcde-g-q22": {"point": "SLOはSLAより厳しく設定し、契約違反に気づいて動く余白(バッファ)を確保する。", "eg": "制限速度ちょうどを自分の運転目標にすると、少し気を抜いただけで即座に速度超過になる。少し余裕を持った目標で走った方が安全、というのと同じ発想。"}, "gcp-pcde-g-q23": {"point": "トラフィックが無い時間帯でも一貫して検証したいなら合成モニタリング、実環境の体感品質を掴みたいならRUM。両方を使う。", "eg": "定期便のテストフライトは乗客がいなくても毎日決まった時間に飛んで確認できるが、実際の乗客アンケートは本物の体験を集められる代わりに乗客が少ないと回答数が集まらない。両方があって初めて全体像がわかる。"}, "gcp-pcde-g-q24": {"point": "想定される負荷に耐えられるか確認したいなら、本番相当の環境で実際にその負荷をかけて試す。", "eg": "マラソン大会の前に本番のコースで練習走行をしておけば、坂道での息切れに気づいて対策できる。ぶっつけ本番では途中で足が止まっても打つ手がない。"}, "gcp-pcde-g-q25": {"point": "ロールバックを待たずに影響を止めたいなら、あらかじめ機能単位のキルスイッチを用意しておく。", "eg": "家全体のブレーカーを落とすのではなく、問題のある1つのコンセントだけのスイッチを切れば、他の部屋の電気は使い続けられる、というのと同じ。"}, "gcp-pcde-g-q26": {"point": "下流が処理しきれないときは、黙って溜め込まず、上流にペースダウンを伝える(バックプレッシャー)。", "eg": "工場の組み立てラインが処理しきれなくなったら、前工程に「もう受け取れない」のサインを出して供給ペースを落としてもらう。サインを出さずに受け入れ続けると、部品に埋もれてしまう。"}, "gcp-pcde-g-q27": {"point": "社内向けプラットフォームチームでも、利用者(社内開発者)の体験を測る指標(ビルド成功率・待ち時間)をSLIにする。", "eg": "社外のお客様向けの店だけでなく、社内の職人に道具を貸す道具屋も、道具の使い勝手や納期という顧客満足の指標を持つべき、という考え方。"}, "gcp-pcde-g-q28": {"point": "時系列を正確に再構築したいなら、記憶や証言ではなく複数の客観的な記録を突き合わせる。", "eg": "事故の状況を目撃者の記憶だけに頼らず、ドライブレコーダーの映像や信号の切り替え記録、通報の時刻を突き合わせて再現するのと同じ。"}, "gcp-pcde-g-q29": {"point": "カオスエンジニアリングは、まず小さい範囲で試し、信頼を積み上げながら段階的に範囲を広げる。", "eg": "新しい避難訓練の手法を、いきなり全社ビルで一斉に試すのではなく、まず1つの部署で試してから徐々に対象を広げていく、というのと同じ。"}, "gcp-pcde-g-q30": {"point": "結果整合性のあるシステムでは、その前提をアプリ設計とSLI設計の両方に織り込み、必要な箇所だけ個別に手当てする。", "eg": "本店で記帳した内容が支店の台帳に反映されるまで少し時間がかかることを織り込んだ上で、直後の照会が必須な業務だけ別の工夫をしておく、という考え方。"}, "gcp-pcde-g-q31": {"point": "長時間インシデントでは、進捗がなくても定期的に更新し、次の更新予定時刻も伝える。", "eg": "飛行機が遅延している時、「引き続き調査中です、次のご案内は30分後です」という機内アナウンスがあれば乗客は安心できる。何もアナウンスがない方がよほど不安にさせる。"}, "gcp-pcde-g-q32": {"point": "ゾーン障害に耐えたいなら、必要量ちょうどではなくN+1分の余剰キャパシティを確保する。", "eg": "3本の柱でちょうど屋根を支えている建物は、1本折れた瞬間に崩れてしまう。あらかじめ1本分余分な柱を用意しておけば持ちこたえられる。"}, "gcp-pcde-g-q33": {"point": "監視バックエンドを将来変える可能性があるなら、OpenTelemetryで計装し、Collector経由でエクスポート先を切り替えられるようにする。", "eg": "電源プラグの共通規格で家電を作っておけば、コンセントの向こうの電力会社が変わっても家電自体は作り替えなくて済む、というのと同じ。"}, "gcp-pcde-g-q34": {"point": "非同期メッセージングをまたいでトレースを連結したいなら、メッセージ属性にトレースコンテキストを載せて伝播させる。", "eg": "リレー競走でバトンを確実に渡せば走者が変わっても同じレースとして記録される。バトンを渡さずに次の走者が勝手に走り始めると別々のレースになってしまう。"}, "gcp-pcde-g-q35": {"point": "アラート疲れの兆候を継続的に把握したいなら、ページの発生件数自体をメタ指標として時系列で観察する。", "eg": "平熱から少しずつ体温が上がってきた段階で異変に気づけるように、呼び出し回数そのものを体温計のように定期的に測っておく、という発想。"}, "gcp-pcde-g-q36": {"point": "コストの急増を早期に検知したいなら、月末の請求書を待たず予算アラートを設定する。", "eg": "クレジットカードの利用明細を月末にまとめて見るのではなく、一定額を超えたら即座に通知が来る設定にしておけば、使いすぎに早く気づける。"}, "gcp-pcde-g-q37": {"point": "テキストの正規表現マッチングで誤カウントが起きるなら、ログを構造化して特定フィールドの値を条件にする。", "eg": "曖昧な手書きのメモから特定のキーワードを拾おうとすると誤検出が起きやすいが、あらかじめ決まった記入欄に正確な値を書いておけば、その欄だけ見れば確実に正しい情報が取れる。"}, "gcp-pcde-g-q38": {"point": "複数の監視ツールを行き来する手間を減らしたいなら、データを1つのダッシュボードへ集約する(single pane of glass)。", "eg": "複数の部署の窓口を1つずつ回るのではなく、1つの総合受付ですべての部署の情報を確認できるようにするイメージ。"}, "gcp-pcde-g-q39": {"point": "誤検知が多いアラートを直したいなら、しきい値を上げて音量を下げるのではなく、誤検知のパターンを分析して条件そのものの精度を上げる。", "eg": "魚群探知機が魚以外にも頻繁に反応するなら、感度を下げて反応を減らすのではなく、反応パターンを分析して本当の魚への精度を高めるべき、というのと同じ。"}, "gcp-pcde-g-q40": {"point": "ヘルスチェックはプロセスの生存確認だけでなく、重要な依存先への疎通確認まで含めて実際の稼働可否を反映させる。", "eg": "お店の看板が営業中のままでも、仕入れ先から商品が届かず商売ができない状態なら、看板を準備中に変えるべき。プロセスの起動だけを見るのは看板だけ見て実態を見ていないのと同じ。"}, "gcp-pcde-g-q41": {"point": "直近は高精細、古いデータは粗い精度で長期保存する段階的な保持階層(ダウンサンプリング)で、コストと分析ニーズを両立する。", "eg": "天気予報で、直近は1時間単位の細かい情報が必要だが、10年前の気候データは月単位の平均値で十分、というのと同じ発想。"}, "gcp-pcde-g-q42": {"point": "通知に関連ダッシュボードや変更履歴へのリンクを含めるのは、初動の調査時間を減らして復旧を速くするため。", "eg": "救急搬送の連絡に患者の基本情報や検査結果へのリンクが添えられていれば、受け入れ側はすぐ準備を始められる。情報がなければ一から確認作業を始めることになり初動が遅れる。"}, "gcp-pcde-g-q43": {"point": "書き込み直後に古いデータが読めるなら、まずリードレプリカのレプリケーションラグを疑う。", "eg": "本社で承認した最新の在庫情報が各支店の端末に反映されるまでには配信時間がかかる。承認直後に支店で確認すると、まだ古い数字が表示されることがある。"}, "gcp-pcde-g-q44": {"point": "夜間バッチで数百GBを一括投入するなら、ストリーミング挿入ではなくCloud Storage経由のバッチロードを使う。", "eg": "引っ越しの荷物を1つずつ手で運ぶより、家一軒分ならトラックでまとめて一括搬送する方が速くて経済的、というのと同じ。"}, "gcp-pcde-g-q45": {"point": "国内限定という規制と冗長性を両立したいなら、国内のリージョナルバケットか国内デュアルリージョンを選ぶ。", "eg": "貴重品を海外の複数の金庫に分散させると規制違反になるが、国内の複数の建物に分散させれば国内限定のルールを守りながら1つの建物が被災しても他でカバーできる。"}, "gcp-pcde-g-q46": {"point": "HPAが増減を頻繁に繰り返す(スラッシング)なら、スケールダウンの安定化ウィンドウで様子見の猶予を設ける。", "eg": "エアコンの温度調整で、室温が一瞬下がっただけですぐ設定を切り替えると落ち着かない。しばらく様子を見てから調整する猶予を持たせれば無駄な切り替えを防げる。"}, "gcp-pcde-g-q47": {"point": "最小インスタンスを確保してもなお残るコールドスタートの遅さには、起動時CPUブーストで起動そのものを速くする。", "eg": "車の発進時だけアクセルを強く踏み込んで素早く加速し、巡航速度に達したら通常のペースに戻す、というイメージ。"}, "gcp-pcde-g-q48": {"point": "接続プールの必要数を理屈で見積もりたいなら、Littleの法則(スループット×平均レイテンシ)を使う。", "eg": "レストランの必要な席数は、1時間あたりの来客数と1人あたりの滞在時間から計算できる。勘で席数を決める必要はない。"}, "gcp-pcde-g-q49": {"point": "同じ相手への接続確立が頻発してレイテンシが問題なら、キープアライブで接続そのものを使い回す。", "eg": "取引先に電話をかけるたびに毎回新しく電話回線を契約するのは非効率で、一度つないだ電話を保留にして次の会話でもそのまま使う方が手間を大きく減らせる。"}, "gcp-pcde-g-q50": {"point": "シングルトンとして動かなければならない役割は、人数を増やす(水平)のではなく、その1台の性能を上げる(垂直)しかない。", "eg": "会社の代表者は1人と決まっているので、代表者を増やすわけにはいかない。その代表者により優秀なアシスタントや道具を与えることでしか、処理能力を高められない。"}, "gcp-pcde-g-q51": {"point": "Gemini CLIが直接操作できるのはGoogle Cloud側のリソースだけで、オンプレミス側は対象外と理解しておく。", "eg": "通訳者は会議室の中でのやり取りは手伝えても、隣のビルにある別の会社の話し合いにまでは入っていけない、というような境界のイメージ。"}, "gcp-pcde-g-q52": {"point": "MLの再学習パイプラインは、コード変更だけでなくデータ到着やモデル精度の劣化検知もトリガーに加える。", "eg": "果物の鮮度は箱を開けなくても時間が経てば落ちていくように、モデルの精度もコードを触らなくてもデータの変化だけで劣化していく。だから劣化そのものを見張るセンサーが要る。"}, "gcp-pcde-g-q53": {"point": "Gemini Cloud Assistは分析・仮説提示までを担い、ロールバックや設定変更の実行権限は持たせない。", "eg": "相談役の医師は診断や仮説を的確に出してくれるが、メスを握って手術を実行するのは別の担当者、という役割分担のイメージ。"}, "gcp-pcde-g-q54": {"point": "Active Assistの推奨事項への対応は一度きりで終わらせず、使用状況の変化に応じて継続的に確認し続ける。", "eg": "一度部屋を片付けても、生活していればまた物が増えていくように、リソースの使用状況も変化し続けるので定期的な見直しが要る。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'gcp-pcde-g')
  AND q.explanation_data IS NOT NULL;

COMMIT;
